/**
 * let implementation of the Navier-Stokes-let from
 * http://www.dgp.toronto.edu/people/stam/reality/Research/pdf/GDC03.pdf
 */

let fluidSolver;
let visc, diff, vScale, velocityScale;
let limitVelocity;
let oldMouseX = 1, oldMouseY = 1;
let numParticles;
let particles;
let c = color(255);
let vectors = false;

function setup() {
  createCanvas(1112, 834);
  fluidSolver = new NavierStokesSolver();
  numParticles = int(pow)(2, 16);
  particles = new Array(numParticles);
  visc = 0.00025;
  diff = 0.03;
  velocityScale = 10;
  vectors = true;
  limitVelocity =10;
  initParticles();
}

function initParticles() {
  for (i = 0; i < numParticles - 1; i++) {
    particles[i] = new Particle();
    particles[i].x = random(width);
    particles[i].y = random(height);
  }
}

function draw() {
  handleMouseMotion();
  background(100,70,0);
  let dt = 1 / frameRate;
  fluidSolver.tick(dt, visc, diff);
  vScale = velocityScale * 60. / frameRate;
  drawParticlesPixels();
}

function drawParticlesPixels() {
  let n = NavierStokesSolver.N;
  let cellHeight = height / n;
  let cellWidth = width / n;
  for (let p of particles) {
    if (p != null) {
      let cellX = floor(p.x / cellWidth);
      let cellY = floor(p.y / cellHeight);
      let dx = float(fluidSolver.getDx)(cellX, cellY);
      let dy = float(fluidSolver.getDy)(cellX, cellY);
      let lX = p.x - cellX * cellWidth - cellWidth / 2;
      let lY = p.y - cellY * cellHeight - cellHeight / 2;
      let v, h, vf, hf;
      if (lX > 0) {
        v = Math.min(n, cellX + 1);
        vf = 1;
      } 
      else {
        v = Math.max(0, cellX - 1);
        vf = -1;
      }
      if (lY > 0) {
        h = Math.min(n, cellY + 1);
        hf = 1;
      } 
      else {
        h = Math.max(0, cellY - 1);
        hf = -1;
      }
      let dxv = float(fluidSolver.getDx)(v, cellY);
      let dxh = float(fluidSolver.getDx)(cellX, h);
      let dxvh = float(fluidSolver.getDx)(v, h);
      let dyv = float(fluidSolver.getDy)(v, cellY);
      let dyh = float(fluidSolver.getDy)(cellX, h);
      let dyvh = float(fluidSolver.getDy)(v, h);
      dx = lerp(lerp(dx, dxv, vf * lX / cellWidth), 
      lerp(dxh, dxvh, vf * lX / cellWidth), 
      hf * lY / cellHeight);
      dy = lerp(lerp(dy, dyv, vf * lX / cellWidth), 
      lerp(dyh, dyvh, vf * lX / cellWidth), 
      hf * lY / cellHeight);
      p.x += dx * vScale;
      p.y += dy * vScale;
      if (p.x < 0 || p.x >= width) {
        p.x = random(width);
      }
      if (p.y < 0 || p.y >= height) {
        p.y = random(height);
      }
      set(int(p.x), int(p.y), c);
    }
  }
}

function handleMouseMotion() {
  window.simulatedMouseX = max(1, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))));
  window.simulatedMouseY = max(1, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  var n = NavierStokesSolver.N;
  var cellHeight = height / n;
  var cellWidth = width / n;
  let mouseDx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - oldMouseX;
  let mouseDy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - oldMouseY;
  var cellX = floor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / cellWidth);
  var cellY = floor((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / cellHeight);
 // mouseDx = (abs(mouseDx) > limitVelocity) ? Math.signum(mouseDx) * limitVelocity : mouseDx;
 // mouseDy = (abs(mouseDy) > limitVelocity) ? Math.signum(mouseDy) * limitVelocity : mouseDy;
  fluidSolver.applyForce(cellX, cellY, mouseDx, mouseDy);
  oldMouseX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  oldMouseY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
}

class Particle {
  x;
  y;
}


class NavierStokesSolver {
  N = 16;
  let SIZE = (N + 2) * (N + 2);
  let u = new Array(SIZE);
  var v = new Array(SIZE);
  let u_prev = new Array(SIZE);
  let v_prev = new Array(SIZE);
  //  let dense = new Array(SIZE);
  //  let dense_prev = new Array(SIZE);

  constructor() {
  }

  getDx(x, y) {
    return u[INDEX(x + 1, y + 1)];
  }

  getDy(x, y) {
    return v[INDEX(x + 1, y + 1)];
  }

  function applyForce(cellX, cellY, vx, vy) {
    cellX += 1;
    cellY += 1;
    var dx = u[INDEX(cellX, cellY)];
    var dy = v[INDEX(cellX, cellY)];

    u[INDEX(cellX, cellY)] = (vx != 0) ? lerp(float(vx), 
      float(dx), 0.85) : dx;
    v[INDEX(cellX, cellY)] = (vy != 0) ? lerp(float(vy), 
      float(dy), 0.85) : dy;
  }

  function tick(dt, visc, diff) {
    vel_step(u, v, u_prev, v_prev, visc, dt);
  }

  // method used to be 'static' since this class is not a top level type
  INDEX(i, j) {
    return i + (N + 2) * j;
  }

  let tmp = new Array(SIZE);

  // same applies to the swap operation ^^
  function SWAP(x0, x) {
   arraycopy(x0, 0, tmp, 0, SIZE);
   arraycopy(x, 0, x0, 0, SIZE);
   arraycopy(tmp, 0, x, 0, SIZE);
  }

  function add_source(x, s, dt) {
    let i, size = (N + 2) * (N + 2);
    for (i = 0; i < size; i++)
      x[i] += dt * s[i];
  }

  function diffuse(b, x, x0, diff, dt) {
    var i, j, k;
    let a = dt * diff * N * N;
    for (k = 0; k < 20; k++) {
      for (i = 1; i <= N; i++) {
        for (j = 1; j <= N; j++) {
          x[INDEX(i, j)] = (x0[INDEX(i, j)] + a
            * (x[INDEX(i - 1, j)] + x[INDEX(i + 1, j)]
            + x[INDEX(i, j - 1)] + x[INDEX(i, j + 1)]))
            / (1 + 4 * a);
        }
      }
      set_bnd(b, x);
    }
  }

  function advect(b, d, d0, u, v, 
    dt) {
    var i, j, i0, j0, i1, j1;
    let x, y, s0, t0, s1, t1, dt0;
    dt0 = dt * N;
    for (i = 1; i <= N; i++) {
      for (j = 1; j <= N; j++) {
        x = i - dt0 * u[INDEX(i, j)];
        y = j - dt0 * v[INDEX(i, j)];
        if (x < 0.5)
          x = 0.5;
        if (x > N + 0.5)
          x = N + 0.5;
        i0 = int(x);
        i1 = i0 + 1;
        if (y < 0.5)
          y = 0.5;
        if (y > N + 0.5)
          y = N + 0.5;
        j0 = int(y);
        j1 = j0 + 1;
        s1 = x - i0;
        s0 = 1 - s1;
        t1 = y - j0;
        t0 = 1 - t1;
        d[INDEX(i, j)] = s0
          * (t0 * d0[INDEX(i0, j0)] + t1 * d0[INDEX(i0, j1)])
          + s1
          * (t0 * d0[INDEX(i1, j0)] + t1 * d0[INDEX(i1, j1)]);
      }
    }
    set_bnd(b, d);
  }

  function set_bnd(b, x) {
    var i;
    for (i = 1; i <= N; i++) {
      x[INDEX(0, i)] = (b == 1) ? -x[INDEX(1, i)] : x[INDEX(1, i)];
      x[INDEX(N + 1, i)] = b == 1 ? -x[INDEX(N, i)] : x[INDEX(N, i)];
      x[INDEX(i, 0)] = b == 2 ? -x[INDEX(i, 1)] : x[INDEX(i, 1)];
      x[INDEX(i, N + 1)] = b == 2 ? -x[INDEX(i, N)] : x[INDEX(i, N)];
    }
    x[INDEX(0, 0)] = 0.5 * (x[INDEX(1, 0)] + x[INDEX(0, 1)]);
    x[INDEX(0, N + 1)] = 0.5 * (x[INDEX(1, N + 1)] + x[INDEX(0, N)]);
    x[INDEX(N + 1, 0)] = 0.5 * (x[INDEX(N, 0)] + x[INDEX(N + 1, 1)]);
    x[INDEX(N + 1, N + 1)] = 0.5 * (x[INDEX(N, N + 1)] + x[INDEX(N + 1, N)]);
  }

  function dens_step(x, x0, u, v, 
    diff, dt) {
    add_source(x, x0, dt);
    SWAP(x0, x);
    diffuse(0, x, x0, diff, dt);
    SWAP(x0, x);
    advect(0, x, x0, u, v, dt);
  }

  function vel_step(u, v, u0, v0, 
    visc, dt) {
    diffuse(1, u, u, visc, dt);
    diffuse(2, v, v, visc, dt);
    project(u, v, u0, v0);
  }

  function project(u, v, p, div) {
    var i, j, k;
    let h;
    h = 1.0 / N;
    for (i = 1; i <= N; i++) {
      for (j = 1; j <= N; j++) {
        div[INDEX(i, j)] = -0.5
          * h
          * (u[INDEX(i + 1, j)] - u[INDEX(i - 1, j)]
          + v[INDEX(i, j + 1)] - v[INDEX(i, j - 1)]);
        p[INDEX(i, j)] = 0;
      }
    }
    set_bnd(0, div);
    set_bnd(0, p);
    for (k = 0; k < 20; k++) {
      for (i = 1; i <= N; i++) {
        for (j = 1; j <= N; j++) {
          p[INDEX(i, j)] = (div[INDEX(i, j)] + p[INDEX(i - 1, j)]
            + p[INDEX(i + 1, j)] + p[INDEX(i, j - 1)] + p[INDEX(
            i, j + 1)]) / 4;
        }
      }
      set_bnd(0, p);
    }
    for (i = 1; i <= N; i++) {
      for (j = 1; j <= N; j++) {
        u[INDEX(i, j)] -= 0.5
          * (p[INDEX(i + 1, j)] - p[INDEX(i - 1, j)]) / h;
        v[INDEX(i, j)] -= 0.5
          * (p[INDEX(i, j + 1)] - p[INDEX(i, j - 1)]) / h;
      }
    }
    set_bnd(1, u);
    set_bnd(2, v);
  }
}

